def find_reversible_subsequence(n, values):
    # Find the longest increasing subsequence (LIS)
    lis = []
    for value in values:
        pos = binary_search(lis, value)
        if pos == len(lis):
            lis.append(value)
        else:
            lis[pos] = value

    # If the entire array is already sorted, return "impossible"
    if len(lis) == n:
        return "impossible"

    # Find the point where the LIS ends and the rest starts
    lis_end = len(lis)
    for i in range(lis_end, n):
        if values[i] < values[i - 1]:
            break

    # Find the point where the reverse of the subsequence should start
    for j in range(lis_end - 1, -1, -1):
        if values[j] > values[j + 1]:
            break

    # Check if reversing the subsequence from j+1 to i-1 can sort the array
    if j == -1 or i == n:
        return "impossible"

    # Verify if reversing the subsequence works
    reversed_values = values[:j+1] + values[j+1:i][::-1] + values[i:]
    if reversed_values == sorted(values):
        return f"{j+2} {i}"

    return "impossible"

def binary_search(lis, value):
    low, high = 0, len(lis)
    while low < high:
        mid = (low + high) // 2
        if lis[mid] < value:
            low = mid + 1
        else:
            high = mid
    return low

