import sys

def find_reversible_subsequence(n, v):
    # Find the first index where the sequence is not increasing
    start = -1
    for i in range(n - 1):
        if v[i] > v[i + 1]:
            start = i
            break

    # If already sorted
    if start == -1:
        return "impossible"

    # Find the last index where the sequence is not increasing
    end = -1
    for i in range(n - 1, 0, -1):
        if v[i] < v[i - 1]:
            end = i
            break

    # Check if reversing the subarray from start+1 to end will sort the array
    # Check left boundary
    if start > 0 and v[start] > v[end]:
        return "impossible"

    # Check right boundary
    if end < n - 1 and v[start + 1] < v[end + 1]:
        return "impossible"

    # Check if the subarray between start and end is sorted in decreasing order
    for i in range(start + 1, end):
        if v[i] < v[i + 1]:
            return "impossible"

    return f"{start + 1} {end + 1}"

